        "ko": "테러리스트들은 우리의 목표를 바꾸고 야망을 멈출 수 있을 것이라 생각했습니다. 하지만 제 삶에서 변한 것은 이것뿐입니다. 나약함과 두려움, 절망은 죽었습니다. 그리고 힘과 능력, 용기가 태어났습니다. 저는 변함없는 말랄라입니다. 제 꿈과 희망, 열망은 여전히 같습니다. 우리는 침묵을 강요당할 때 비로소 목소리의 소중함을 깨닫습니다.",
